<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Universe Civilization: Empire at Wars Colony & Fleet Command</title><style>:root{--ink:#0b0b0b;--muted:#666;--line:#ddd;--soft:#fafafa;--good:#176b3a;--warn:#8a5b00;--bad:#a11}*{box-sizing:border-box}body{margin:0;background:#fff;color:var(--ink);font-family:Inter,system-ui,sans-serif}.shell{display:grid;grid-template-columns:260px 1fr;min-height:100vh}.sidebar{border-right:1px solid var(--line);padding:20px;position:sticky;top:0;height:100vh;overflow:auto}.brand{font-weight:900;letter-spacing:.13em;font-size:12px;padding:8px 0 20px;border-bottom:1px solid var(--line)}.nav{display:grid;gap:7px;margin-top:20px}.nav button{border:0;background:#fff;color:#111;text-align:left;padding:11px;cursor:pointer;min-height:44px;border-radius:5px}.nav button.active,.nav button:hover{background:#111;color:#fff}.main{min-width:0}.top{border-bottom:1px solid var(--line);padding:16px 26px;display:flex;justify-content:space-between;gap:18px;align-items:center;flex-wrap:wrap}.hud{display:flex;gap:22px;flex-wrap:wrap}.hud small{display:block;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}.hud strong{font-size:16px}.content{padding:26px;max-width:1450px}.heading{display:flex;justify-content:space-between;gap:20px;align-items:start;border-bottom:1px solid var(--line);padding-bottom:20px;margin-bottom:20px}.heading h1{font-size:34px;letter-spacing:-.05em;margin:4px 0}.heading p{color:var(--muted);max-width:700px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.wide{grid-column:span 2}.card{border:1px solid var(--line);background:var(--soft);padding:18px}.card h2{margin-top:0;font-size:18px}.metric{background:#fff;border:1px solid var(--line);padding:14px}.metric strong{font-size:26px;display:block}.metric small{color:var(--muted)}.bar{height:10px;background:#e8e8e8;margin-top:9px}.bar i{display:block;height:100%;background:#111}.status{border:1px solid var(--line);padding:9px 11px;font-size:12px}.status.good{border-color:var(--good);color:var(--good)}.status.warn{border-color:var(--warn);color:var(--warn)}.status.bad{border-color:var(--bad);color:var(--bad)}.button{border:1px solid #111;background:#fff;color:#111;padding:10px 13px;cursor:pointer;min-height:44px}.button.dark{background:#111;color:#fff}.button:focus-visible,.nav button:focus-visible,select:focus-visible,input:focus-visible{outline:3px solid #777;outline-offset:2px}.form{display:grid;gap:10px}.form label{font-size:12px;font-weight:700}.form select,.form input{border:1px solid #aaa;padding:10px;background:#fff;min-height:44px}.row{display:flex;gap:8px;flex-wrap:wrap}.table{width:100%;border-collapse:collapse}.table th,.table td{text-align:left;border-bottom:1px solid var(--line);padding:11px 7px}.table th{font-size:11px;text-transform:uppercase;letter-spacing:.08em}.pill{border:1px solid #999;padding:4px 8px;font-size:11px;display:inline-block;margin:2px}@media(max-width:850px){.shell{grid-template-columns:1fr}.sidebar{position:relative;height:auto;max-height:360px;border-right:0;border-bottom:1px solid var(--line)}.grid{grid-template-columns:1fr}.wide{grid-column:auto}.content{padding:18px}.button{width:100%}}</style></head><body><div class="shell"><aside class="sidebar"><div class="brand">UNIVERSE CIVILIZATION: EMPIRE AT WARS / COLONY OPS</div><nav class="nav"><button class="active" data-view="overview">Colony Overview</button><button data-view="life">Food & Water</button><button data-view="buildings">Buildings Queue</button><button data-view="fleets">Fleet Dispatch</button><button data-view="missions">Mission Log</button></nav></aside><main class="main"><header class="top"><div class="hud"><span><small>Active Colony</small><strong id="hudColony">Asteria Prime</strong></span><span><small>Population</small><strong id="hudPop">100</strong></span><span><small>Food</small><strong id="hudFood">975</strong></span><span><small>Water</small><strong id="hudWater">980</strong></span><span><small>Fleet</small><strong>3,240</strong></span></div><div class="row"><button class="button" id="tick">Process 1 hour</button><button class="button dark" id="dispatch">Dispatch fleet</button></div></header><section class="content"><div class="heading"><div><div class="eyebrow" id="eyebrow">COLONY MANAGEMENT</div><h1 id="title">Colony Overview</h1><p id="desc">Monitor life support, population, construction, and fleet operations from one command surface.</p></div><div class="status good" id="status">Systems nominal</div></div><div id="view"></div></section></main></div><script>const state={population:100,capacity:1000,food:975,water:980,morale:1,colonies:['Asteria Prime','Haven-7','Erebus Outpost'],missions:[{type:'Explore',target:'Orion Gate',status:'Outbound',eta:'18:24'},{type:'Transport',target:'Haven-7',status:'Returning',eta:'06:10'}],queue:[{item:'Residential Hub',level:3,done:'12:40'},{item:'Scout Squadron',level:1,done:'04:20'}]};const views={overview:{title:'Colony Overview',desc:'Monitor life support, population, construction, and fleet operations from one command surface.'},life:{title:'Food & Water',desc:'Life support is calculated server-side every colony tick. Shortage stops population growth.'},buildings:{title:'Buildings Queue',desc:'Queue resource, life-support, residential, shipyard, research, and defense upgrades.'},fleets:{title:'Fleet Dispatch',desc:'Send transport, attack, raid, colonize, explore, recycle, or espionage missions.'},missions:{title:'Mission Log',desc:'Review outbound, arrived, returning, completed, failed, and cancelled missions.'}};function render(view='overview'){const v=views[view];document.getElementById('title').textContent=v.title;document.getElementById('desc').textContent=v.desc;document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));let html='';if(view==='overview')html=`<div class="grid"><div class="card"><h2>Life Support</h2><div class="row"><div class="metric"><small>Food</small><strong>${state.food}</strong><div class="bar"><i style="width:${Math.min(100,state.food/10)}%"></i></div></div><div class="metric"><small>Water</small><strong>${state.water}</strong><div class="bar"><i style="width:${Math.min(100,state.water/10)}%"></i></div></div></div><p class="status good">No shortage detected · population growth active</p></div><div class="card"><h2>Population</h2><div class="metric"><small>Current / capacity</small><strong>${state.population} / ${state.capacity}</strong><div class="bar"><i style="width:${state.population/state.capacity*100}%"></i></div></div><p>Morale multiplier: <b>${state.morale.toFixed(2)}</b></p></div><div class="card"><h2>Colony Network</h2>${state.colonies.map((x,i)=>`<div class="status ${i===0?'good':''}">${x} · ${i===0?'Active':'Stable'}</div>`).join('')}</div><div class="card wide"><h2>Construction Queue</h2>${state.queue.map(x=>`<div class="status">${x.item} · level ${x.level} · completes in ${x.done}</div>`).join('')}</div><div class="card"><h2>Fleet Status</h2>${state.missions.map(x=>`<div class="status">${x.type} → ${x.target} · ${x.status}</div>`).join('')}</div></div>`;if(view==='life')html=`<div class="grid"><div class="card"><h2>Hourly Formula</h2><p>Food cost = ceil(population × 0.25 × hours)</p><p>Water cost = ceil(population × 0.20 × hours)</p><p>Growth = floor(population × 0.01 × hours × morale)</p></div><div class="card"><h2>Simulation</h2><div class="metric"><small>Next one-hour tick</small><strong>Food ${Math.max(0,state.food-Math.ceil(state.population*.25))}</strong><span>Water ${Math.max(0,state.water-Math.ceil(state.population*.2))}</span></div><p class="status good">Growth remains enabled while both stocks stay above zero.</p></div><div class="card"><h2>Controls</h2><div class="form"><label>Production policy<select><option>Balanced</option><option>Food priority</option><option>Water priority</option></select></label><button class="button dark" onclick="alert('Server action: colony_update')">Save policy</button></div></div></div>`;if(view==='buildings')html=`<div class="grid"><div class="card wide"><h2>Active Queue</h2><table class="table"><thead><tr><th>Item</th><th>Level</th><th>Completion</th><th>Status</th></tr></thead><tbody>${state.queue.map(x=>`<tr><td>${x.item}</td><td>${x.level}</td><td>${x.done}</td><td><span class="pill">Queued</span></td></tr>`).join('')}</tbody></table></div><div class="card"><h2>Queue building</h2><div class="form"><label>Building<select><option>Food Farm</option><option>Water Processor</option><option>Residential Hub</option><option>Shipyard</option><option>Research Lab</option></select></label><label>Level<input type="number" value="1" min="1" max="50"></label><button class="button dark" onclick="alert('Server action: queue_building')">Queue upgrade</button></div></div></div>`;if(view==='fleets')html=`<div class="grid"><div class="card wide"><h2>Dispatch Mission</h2><div class="form"><label>Source colony<select><option>Asteria Prime</option><option>Haven-7</option><option>Erebus Outpost</option></select></label><label>Target<select><option>Orion Gate</option><option>Haven-7</option><option>Uncharted sector</option></select></label><label>Mission type<select id="missionType"><option>Transport</option><option>Attack</option><option>Raid</option><option>Colonize</option><option>Explore</option><option>Recycle</option><option>Espionage</option></select></label><div class="row"><button class="button dark" onclick="dispatchMission()">Launch mission</button><button class="button" onclick="alert('Server action: fleet preview')">Preview travel</button></div></div></div><div class="card"><h2>Fleet Composition</h2><div class="metric"><small>Scouts</small><strong>2,000</strong></div><div class="metric"><small>Raiders</small><strong>800</strong></div><div class="metric"><small>Carriers</small><strong>440</strong></div></div></div>`;if(view==='missions')html=`<div class="card"><h2>Mission Log</h2><table class="table"><thead><tr><th>Type</th><th>Target</th><th>Status</th><th>ETA</th></tr></thead><tbody>${state.missions.map(x=>`<tr><td>${x.type}</td><td>${x.target}</td><td>${x.status}</td><td>${x.eta}</td></tr>`).join('')}</tbody></table></div>`;document.getElementById('view').innerHTML=html}function processTick(){const foodCost=Math.ceil(state.population*.25),waterCost=Math.ceil(state.population*.2);state.food=Math.max(0,state.food-foodCost);state.water=Math.max(0,state.water-waterCost);const shortage=state.food===0||state.water===0;if(!shortage)state.population=Math.min(state.capacity,state.population+Math.floor(state.population*.01*state.morale));document.getElementById('hudPop').textContent=state.population;document.getElementById('hudFood').textContent=state.food;document.getElementById('hudWater').textContent=state.water;document.getElementById('status').textContent=shortage?'Life support shortage':'Systems nominal';document.getElementById('status').className='status '+(shortage?'bad':'good');render('overview')}function dispatchMission(){const type=document.getElementById('missionType').value;state.missions.unshift({type,target:'Selected target',status:'Outbound',eta:'22:00'});alert('Mission queued: '+type);render('missions')}document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>render(b.dataset.view));document.getElementById('tick').onclick=processTick;document.getElementById('dispatch').onclick=()=>render('fleets');render();</script></body></html>
